(function(){'use strict';const $=s=>document.querySelector(s),M=InventoryLoss,owner=KashierData.userId();let snapshot=null,request=0;const active=()=>Boolean(owner)&&KashierData.loggedIn()&&KashierData.userId()===owner;
function node(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);return e;}
function clear(){snapshot=null;$('#loss-paper').hidden=true;for(const id of ['rows','summary'])$('#loss-'+id).replaceChildren();$('#loss-meta').textContent=$('#loss-coverage').textContent='';$('#loss-print').disabled=$('#loss-csv').disabled=true;}
function invalidate(){request++;clear();$('#loss-load').disabled=false;$('#loss-status').textContent='بۆ ماوەی نوێ ڕاپۆرتەکە دووبارە ئامادە بکە.';}
function render(s){$('#loss-meta').textContent=s.from+' → '+s.to+' · کاتی بەغدا · ئامادەکراو: '+s.generated_at;$('#loss-coverage').textContent=s.complete?'تێچووی هەموو '+s.count+' تۆمارەکە دیارە.':'تێچووی '+s.known_count+' لە '+s.count+' تۆمار دیارە؛ کۆی تەواوی تێچوو بەردەست نییە.';const boxes=[['کۆی تەواوی تێچوو / دینار',s.complete?M.money(s.known_cost):'بەردەست نییە'],['کۆی بەشی تێچووزانراو / دینار',s.known_count?M.money(s.known_cost):'—'],['تۆماری تێچووزانراو',s.known_count+' / '+s.count]];for(const k of Object.keys(M.kinds)){const t=s[k];boxes.push([M.kinds[k]+' · کۆی تەواو / دینار',t.count===t.known_count?M.money(t.known_cost):'بەردەست نییە'],[M.kinds[k]+' · بەشی تێچووزانراو / دینار',t.known_count?M.money(t.known_cost):'—'],[M.kinds[k]+' · تۆماری تێچووزانراو',t.known_count+' / '+t.count]);}for(const [label,value] of boxes){const box=node('div');box.append(node('dt',label),node('dd',value));$('#loss-summary').append(box);}for(const r of s.rows){const row=node('tr'),product=node('td'),a=node('a',r.name);a.href='product.html?id='+r.product_id;product.append(a);const source=node('td'),link=node('a','A-'+r.adjustment_no);link.href=(r.kind==='waste'?'waste.html':'stock-adjustment.html')+'?id='+r.id;source.append(link,node('br'),'S-'+r.movement_no);row.setAttribute('data-known',String(r.coverage==='known'));row.append(source,node('td',r.day),product,node('td',M.kinds[r.kind]),node('td',M.quantity(r.quantity_units)),node('td',r.cost_iqd===null?'—':M.money(r.cost_iqd)),node('td',M.coverageLabels[r.coverage]),node('td',r.note));$('#loss-rows').append(row);}$('#loss-empty').hidden=s.count!==0;$('#loss-paper').hidden=false;}
async function load(){invalidate();if(!active()){location.replace('auth.html?next=inventory-loss.html');return;}const mine=++request,from=$('#loss-from').value,to=$('#loss-to').value;try{M.range(from,to);$('#loss-load').disabled=true;$('#loss-status').textContent='ئامادەکردنی ڕاپۆرتی کەمی کۆگا…';const s=await KashierData.getInventoryLossReport(from,to);if(mine!==request)return;if(!active())throw Error('هەژمارەکە گۆڕاوە؛ دووبارە بچۆ ژوورەوە.');M.validate(s,from,to,owner);snapshot=s;render(s);$('#loss-print').disabled=$('#loss-csv').disabled=false;$('#loss-status').textContent='ڕاپۆرت ئامادەیە؛ چاپ و CSV هەمان تۆمارەکان بەکاردەهێنن.';}catch(e){if(mine===request){clear();$('#loss-status').textContent=e.message;}}finally{if(mine===request)$('#loss-load').disabled=false;}}
$('#loss-form').addEventListener('submit',e=>{e.preventDefault();if(!$('#loss-load').disabled)load();});for(const id of ['from','to'])$('#loss-'+id).addEventListener('input',invalidate);
function usable(){if(!active()){invalidate();$('#loss-status').textContent='هەژمارەکە گۆڕاوە؛ دووبارە بچۆ ژوورەوە.';return false;}return Boolean(snapshot);}
$('#loss-print').addEventListener('click',()=>{if(usable())window.print();});$('#loss-csv').addEventListener('click',()=>{if(!usable())return;const url=URL.createObjectURL(new Blob([M.csv(snapshot)],{type:'text/csv;charset=utf-8'})),a=node('a');a.href=url;a.download='kashier-inventory-loss-'+snapshot.from+'-'+snapshot.to+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});window.addEventListener('beforeprint',()=>{if(!active())invalidate();});window.addEventListener('pagehide',invalidate);window.addEventListener('pageshow',e=>{if(e.persisted)invalidate();});const today=M.day(new Date());$('#loss-from').value=today.slice(0,8)+'01';$('#loss-to').value=today;load();
})();
